"""Write evidence-derived ordinary-file collection targets. Does not contact a vehicle."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent
inv=json.loads((R/'source_inventory.json').read_text())
def by_suffix(suffix):
 matches=[{'archive':s['name'],'member':m['path'],'sha256':m['sha256'],'bytes':m['bytes']} for s in inv['sources'] for m in s['members'] if m['path'].endswith(suffix)]
 return matches
rows=[]
def add(domain,path,reason,source,known=None,status='known_file_collect_changed_variant',variant='Installed variant matching the user vehicle; retain version and hash.',maximum=536870912):
 rows.append({'domain':domain,'path':path,'reason':reason,'source_evidence':source,'known_sha256':sorted(set(x['sha256'] for x in known or [])),'known_sources':known or [],'required_variant':variant,'status':status,'maximum_bytes':maximum,'operation':{'kind':'ordinary_file_read','follow_device_symlinks':False,'vehicle_network_command':False,'read_only_command': ['adb','exec-out','sh','-c',"cat -- '"+path+"'"] if domain=='Android' else None,'qconn_operation': 'review exact ordinary path before collection; file_open(O_RDONLY); file_stat; accept regular file only; file_read; file_close; no pre-open lstat available' if domain=='QNX' else None}})
producer=by_suffix('/vendor_bin_smartcore_update_client')[0]
