for path,suffix,why in [('/vendor/bin/smartcore_update_client','/vendor_bin_smartcore_update_client','Correlate actual package-copy branch with installed updater.'),('/system/bin/smartcore_update_client','/system_bin_smartcore_update_client','Existing second updater path; hash-equal copy adds no new semantics.'),('/vendor/etc/usb_reflash_config.json','/vendor/etc/usb_reflash_config.json','Real config selects ECARX/HIGH/folder/udisk_manifest.json; compare changed variants.'),('/system/etc/usb_reflash_config.json','/system/etc/usb_reflash_config.json','Exact default config path appears in updater at VA0xea35; existence and alias to vendor config remain unproven.')]:
 k=by_suffix(suffix);add('Android',path,why,[producer],k,status='known_file_collect_changed_variant' if k else 'conditional_from_producer_code_not_observed_installed')
for path,why in [('/bin/sc_qnx_vip_proxy','Compare the six finite registered SOME/IP handlers with any changed vehicle variant.'),('/bin/can_driver','Compare generic SPI/CAN resource-manager code; do not open the device node.'),('/bin/SwVersionService','Correlate QNX software-version provider.'),('/etc/sw-version-info.txt','Record actual ES/ER QNX version with files.'),('/vm/images_lv/linux-lv.img','If changed, decode updated Linux LV initramfs offline for updater and log handler paths.')]:
 k=by_suffix('/qnx/files'+path);add('QNX',path,why,k,k)
(R/'collection_targets.json').write_text(json.dumps({'scope':'Cruise-specific evidence-derived additions. Existing files should be hash-skipped. No path scanning, launching firmware/updaters, device reads, replay or control writes. Unknown file absence is a valid result.','targets':rows,'not_collectable_through_current_android_qnx_filesystem': [{'domain':'Linux_LV_initramfs_runtime','path_pattern':'/data/kernellog/vp_*.log','proven_directory':'/data/kernellog','proven_prefix':'vp','evidence':'mcu_log SHA33d91dad416089274af3ec23b4e5b8824b69a5196313b3162c40bdfd65e4fd0b VA400a1c..400a3c passes directory and prefix to logging setup; generated names %s/%s_%d.log. Runtime guest alias into Android/QNX not established.','missing_fact':'Mounted location of LV /dev/block/vdb within an already-running accessible filesystem. No new mount or LV boot is authorized.','prohibited_action':'Do not execute mcu_log: callback400c1c performs mkdir and mount.'}],'missing_fact_without_exact_collectable_path':['Production VP/MCU image corresponding to MCU version20.24.10.23024.41141 and hardware identity of 198.18.34.1:50500.','Wheel-switch receiving ECU handler and downstream cruise request/counter/checksum/eligibility semantics.','Meaning/ownership of swlm/swp1 package segments; names alone are insufficient.'],'excluded':['/dev/can*','/dev/spi*','raw block devices','firmware execution','updater execution','vehicle-network messages']},ensure_ascii=False,indent=2))
